WITH metrics AS (SELECT *, SUM(pressure) OVER (PARTITION BY TO_DATE(reading_ts) ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_pressure, CORR(status_bits, pressure) OVER (PARTITION BY MONTH(reading_ts), device_code) AS corr_status_bits_pressure FROM device_readings WHERE firmware IN ('1.0.3', '2.0.1')) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, corr_status_bits_pressure FROM metrics ORDER BY reading_ts;
